"""Regenerate docs/queries.md from the query catalog. Usage: make docs"""

import json

from whygraph.config import REPO_ROOT
from whygraph.graph.queries import CATALOG

OUT = REPO_ROOT / "docs" / "queries.md"


def main() -> None:
    lines = [
        "# Query catalog",
        "",
        "> Generated by `make docs` from `whygraph/graph/queries.py` — do not edit by hand.",
        "> Agents, MCP tools and the UI can only run these queries.",
        "",
    ]
    for q in sorted(CATALOG.values(), key=lambda q: q.code):
        lines += [
            f"## {q.code} · `{q.id}` — {q.title}",
            "",
            q.explain,
            "",
            "```cypher",
            q.cypher,
            "```",
            "",
            f"Example params: `{json.dumps(q.example_params)}`",
            "",
        ]
    OUT.write_text("\n".join(lines))
    print(f"wrote {OUT.relative_to(REPO_ROOT)} ({len(CATALOG)} queries)")


if __name__ == "__main__":
    main()
